// The languages of slot `slot` (bits as above) that write code point `cp`; 0 when
// none of them does, or `cp` is not a letter of that script.
static inline uint64_t uniLetterLangs(int slot, int cp) {
    switch (slot) {
    case 1: return uniMask(kUniLetterLangs1, cp);
    case 2: return uniMask(kUniLetterLangs2, cp);
    case 3: return uniMask(kUniLetterLangs3, cp);
    case 4: return uniMask(kUniLetterLangs4, cp);
    case 5: return uniMask(kUniLetterLangs5, cp);
    case 6: return uniMask(kUniLetterLangs6, cp);
    }
    return 0;
}
// A letter that says nothing beside its script's virama: joined into a conjunct it
// looks like another language's letter (see the generator).
struct UniJoined { int32_t letter, virama; };
#define EV_JOINED_NEUTRAL_COUNT 1
static const UniJoined kUniJoinedNeutral[EV_JOINED_NEUTRAL_COUNT] = {{0x9B0, 0x9CD}};
